std::vector<std::byte> file(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);check(bool(f),"Own bounded input open");const auto n=f.tellg();check(n>0&&n<4000000,"Own bounded image/object extent");std::vector<std::byte>b(static_cast<std::size_t>(n));f.seekg(0);f.read(reinterpret_cast<char*>(b.data()),n);check(bool(f),"Own complete input read");return b;}
std::array<std::byte,3504> bytes(const State&s){std::array<std::byte,3504>b{};std::memcpy(b.data(),&s,3504);return b;}
std::array<std::byte,512> fxbytes(const Runtime&r){std::array<std::byte,512>b{};std::memcpy(b.data(),r.fx().data(),512);return b;}
Cpu32 cpu(const State&s){unsigned f=static_cast<unsigned>(s.rflag.flat)&~0xcd5U;f|=(s.aflag.cf<<0)|(s.aflag.pf<<2)|(s.aflag.af<<4)|(s.aflag.zf<<6)|(s.aflag.sf<<7)|(s.aflag.df<<10)|(s.aflag.of<<11);return {s.gpr.rax.dword,s.gpr.rcx.dword,s.gpr.rdx.dword,s.gpr.rbx.dword,s.gpr.rsp.dword,s.gpr.rbp.dword,s.gpr.rsi.dword,s.gpr.rdi.dword,f,s.gpr.rip.dword};}
void project(State&s,const Cpu32&c){s.gpr.rax.dword=c.eax;s.gpr.rcx.dword=c.ecx;s.gpr.rdx.dword=c.edx;s.gpr.rbx.dword=c.ebx;s.gpr.rsp.dword=c.esp;s.gpr.rbp.dword=c.ebp;s.gpr.rsi.dword=c.esi;s.gpr.rdi.dword=c.edi;s.gpr.rip.dword=c.eip;s.rflag.flat=c.eflags;s.aflag.cf=(c.eflags>>0)&1;s.aflag.pf=(c.eflags>>2)&1;s.aflag.af=(c.eflags>>4)&1;s.aflag.zf=(c.eflags>>6)&1;s.aflag.sf=(c.eflags>>7)&1;s.aflag.df=(c.eflags>>10)&1;s.aflag.of=(c.eflags>>11)&1;}
