class Context;
thread_local Context*owner{};
class Context{
 Runtime&r_;State&s_;const std::thread::id thread_=std::this_thread::get_id();bool running_{};unsigned mode_{};std::vector<Event>events_;Diagnostic first_{};
 void capture(unsigned address,const std::string&why){if(first_.reason.empty())first_={s_.gpr.rip.dword,address,static_cast<unsigned>(events_.size()),why};}
 void after(){const auto n=events_.size();if(mode_==1&&n==1)r_.memory().protect({0x20001000},Permissions::read);if(mode_==2&&n==4)r_.memory().protect(r_.fs_base(),Permissions::none);if(mode_==3&&n==6)r_.memory().protect(r_.fs_base(),Permissions::read);if(mode_==4&&n==13)iat_permission(Permissions::none);if(mode_==5&&n==14)r_.memory().protect({0x20001000},Permissions::read);if(mode_==6&&n==15)r_.memory().store<unsigned>({frame-144},0x12345678);if(mode_==7&&n==13)change(slot,r_.memory().load<unsigned>({slot})+1);}
public:
 Context(Runtime&r,const std::string&native,unsigned seed=0,bool marked=true):r_(r),s_(*std::construct_at(reinterpret_cast<State*>(r.remill_state().data()))){for(unsigned i=0;i<3504;++i)r_.remill_state()[i]=std::byte((0x5b+i*37+(i>>4)+seed*43)&255);std::memset(&s_.addr,0,sizeof(s_.addr));s_.addr.fs_base.dword=r_.fs_base().value;s_.seg.cs.flat=0x23;s_.seg.ds.flat=s_.seg.ss.flat=0x2b;project(s_,{0x11223344U+seed,0x55667788U+seed,0x99aabbccU+seed,0xddeeff00U+seed,frame,0x67891234U+seed,0x34567890U+seed,0x78903456U+seed,0x202,entry});std::memset(&s_.x87,0,sizeof(s_.x87));s_.x87.fxsave.cwd.flat=0x37f;s_.x87.fxsave.mxcsr.flat=0x1f80;s_.x87.fxsave.mxcsr_mask.flat=0x2ffff;s_.sw.ie=s_.sw.de=s_.sw.ze=s_.sw.oe=s_.sw.ue=s_.sw.pe=s_.sw.sf=s_.sw.c0=s_.sw.c1=s_.sw.c2=s_.sw.c3=0;r_.cpu()=cpu(s_);r_.cpu().esp=frame+4;r_.cpu().eip=Runtime::external_return;std::memcpy(r_.fx().data(),&s_.x87,512);if(marked)r_.mark_remill_seeded();std::array<std::byte,4096>pattern{};for(unsigned i=0;i<4096;++i)pattern[i]=std::byte((i*19+seed*7+0x3d)&255);r_.memory().write({0x20001000},pattern);r_.register_translation({{entry},{Abi::Cdecl,0,true},&adapter,"Independent first required CRT service fault",{Domain::admitted_game,m4::admitted_image_hash,430,"30da37cdf0ae957fc87f6e0caf250b4a60e0e63767dea24935381791e60ad856",native,"0c67cae86dad6468e082607ebe9d2b2504094829adb28e37b0c082d6e158d724"}});}
 static void adapter(Runtime&r){if(!owner||&owner->r_!=&r)throw std::runtime_error("Own current adapter owner missing");owner->run();}
 void guard(){if(owner!=this||!running_||thread_!=std::this_thread::get_id())throw std::runtime_error("Own stable serial adapter owner");}
 void run(){if(running_||thread_!=std::this_thread::get_id()||!r_.remill_seeded()){capture(0,"Own serial/seed entry admission");throw std::runtime_error(first_.reason);}std::array<std::byte,430>source{};r_.memory().read({entry},source);if(m4::sha256(source)!="30da37cdf0ae957fc87f6e0caf250b4a60e0e63767dea24935381791e60ad856"){capture(entry,"Own current whole430 source identity");throw std::runtime_error(first_.reason);}project(s_,r_.cpu());running_=true;try{(void)sub_5ac3a0(&s_,entry,this);throw std::runtime_error("Unimplemented entry cannot complete");}catch(...){running_=false;throw;}}
 unsigned read(unsigned a){guard();unsigned v;try{v=r_.memory().load<unsigned>({a});}catch(const std::exception&e){capture(a,e.what());throw;}events_.push_back({s_.gpr.rip.dword,a,v,4,0});after();return v;}
 void write(unsigned a,unsigned v){guard();try{r_.memory().store<unsigned>({a},v);}catch(const std::exception&e){capture(a,e.what());throw;}events_.push_back({s_.gpr.rip.dword,a,v,4,1});after();}
 void*call(State*s,unsigned target){guard();try{check(s==&s_&&events_.size()==15&&events_[13].pc==0x5ac3cf&&events_[13].address==slot&&!events_[13].write&&events_[13].value==target&&events_[14].pc==0x5ac3cf&&events_[14].address==frame-144&&events_[14].value==0x5ac3d5,"Own actual CALL/IAT/guest frame event shape");check(s_.gpr.rsp.dword==frame-144&&r_.memory().load<unsigned>({frame-144})==0x5ac3d5,"Own actual guest CALL return storage");r_.cpu()=cpu(s_);r_.cpu().esp+=4;r_.cpu().eip=0x5ac3cf;r_.call_import({slot},{0x5ac3d5});throw std::runtime_error("First service unavailable; no completion admitted");}catch(const std::exception&e){capture(slot,e.what());throw;}}
 void invoke(unsigned return_pc=Runtime::external_return){if(owner)throw std::runtime_error("Own no nested context owner");owner=this;try{if(return_pc==Runtime::external_return)r_.invoke({entry});else r_.call_direct({entry},{return_pc});}catch(...){owner=nullptr;throw;}owner=nullptr;}
 void mode(unsigned m){mode_=m;}const auto&events()const{return events_;}const auto&diagnostic()const{return first_;}State&state(){return s_;}bool running()const{return running_;}
 void iat_permission(Permissions p){for(const auto&g:r_.image_metadata().mapped_regions)if(slot>=g.start.value&&slot<g.start.value+g.size){r_.memory().protect(g.start,p);return;}throw std::runtime_error("Own owning IAT mapping absent");}
 void change(unsigned a,unsigned v){for(const auto&g:r_.image_metadata().mapped_regions)if(a>=g.start.value&&std::uint64_t{a}+4<=std::uint64_t{g.start.value}+g.size){r_.memory().protect(g.start,Permissions::read|Permissions::write);r_.memory().store<unsigned>({a},v);r_.memory().protect(g.start,g.permissions);return;}throw std::runtime_error("Own mutation mapping absent");}
};
extern "C" unsigned __remill_read_memory_32(void*p,unsigned a)noexcept(false){return static_cast<Context*>(p)->read(a);}
extern "C" unsigned char __remill_read_memory_8(void*,unsigned)noexcept(false){throw std::runtime_error("Unreached byte read");}
extern "C" void*__remill_write_memory_32(void*p,unsigned a,unsigned v)noexcept(false){static_cast<Context*>(p)->write(a,v);return p;}
extern "C" void*__remill_function_call(State*s,unsigned a,void*p)noexcept(false){return static_cast<Context*>(p)->call(s,a);}
extern "C" void*__remill_function_return(State*,unsigned,void*)noexcept(false){throw std::runtime_error("Unreached guest RET");}
