extern "C" void*mw34_crte_enter(State*s,unsigned pc,void*p)noexcept(false){auto*c=static_cast<Context*>(p);c->guard();check(s==&c->state()&&pc==entry,"Own actual ordinary entry pointer/PC");return p;}
