Policy policy(){Policy p;p.stack_low={0x20001000};p.stack_bytes=4096;p.heap_bytes=4096;return p;}
struct Fixture{Runtime r;Context c;Fixture(std::span<const std::byte>g,const std::string&hash,unsigned seed=0,bool marked=true):r(Runtime::from_admitted_image(g,policy())),c(r,hash,seed,marked){r.freeze_registry();}};
struct Memory{std::array<std::byte,8192>pages;std::array<std::byte,16>tib;};
Memory memory(Runtime&r){Memory m{};r.memory().read({0x20001000},std::span{m.pages}.subspan(0,4096));r.memory().read({0x5bb000},std::span{m.pages}.subspan(4096));r.memory().read(r.fs_base(),std::span{m.tib}.subspan(0,4));r.memory().read(r.fs_base().wrapping_add(4),std::span{m.tib}.subspan(4,8));r.memory().read(r.fs_base().wrapping_add(0x18),std::span{m.tib}.subspan(12,4));return m;}
bool same(const Memory&a,const Memory&b){return a.pages==b.pages&&a.tib==b.tib;}
void repair(Fixture&f,unsigned raw,unsigned source){f.c.mode(0);f.r.memory().protect({0x20001000},Permissions::read|Permissions::write);f.r.memory().protect(f.r.fs_base(),Permissions::read|Permissions::write);for(const auto&g:f.r.image_metadata().mapped_regions)if(slot>=g.start.value&&slot<g.start.value+g.size)f.r.memory().protect(g.start,g.permissions);f.c.change(slot,raw);f.c.change(entry+400,source);}
std::array<Event,15> predict(Memory&m,const State&s,unsigned fs){std::array<Event,15>e{};unsigned n{};auto store=[&](unsigned pc,unsigned a,unsigned value){e[n++]={pc,a,value,4,1};if(a==fs)std::memcpy(m.tib.data(),&value,4);else std::memcpy(m.pages.data()+(a-0x20001000),&value,4);};auto load=[&](unsigned pc,unsigned a){unsigned value;std::memcpy(&value,a==fs?m.tib.data():m.pages.data()+4096+(a-0x5bb000),4);e[n++]={pc,a,value,4,0};};const unsigned ext=Runtime::external_return;std::memcpy(m.pages.data()+frame-0x20001000,&ext,4);store(entry,frame-4,s.gpr.rbp.dword);store(0x5ac3a3,frame-8,0xffffffff);store(0x5ac3a5,frame-12,0x5d0f78);store(0x5ac3aa,frame-16,0x5ac586);load(0x5ac3af,fs);store(0x5ac3b5,frame-20,e[4].value);store(0x5ac3b6,fs,frame-20);store(0x5ac3c0,frame-128,s.gpr.rbx.dword);store(0x5ac3c1,frame-132,s.gpr.rsi.dword);store(0x5ac3c2,frame-136,s.gpr.rdi.dword);store(0x5ac3c3,frame-28,frame-136);store(0x5ac3c6,frame-8,0);store(0x5ac3cd,frame-140,2);load(0x5ac3cf,slot);store(0x5ac3cf,frame-144,0x5ac3d5);check(n==15,"Own complete 15 memory-event prefix");return e;}
State expected(const State&s,unsigned raw){State t;std::memcpy(&t,&s,3504);t.gpr.rax.dword=0xffffffff;t.gpr.rbp.dword=frame-4;t.gpr.rsp.dword=frame-144;t.gpr.rip.dword=raw;const unsigned a=frame-20,b=0xffffff98U,v=a+b;t.aflag.cf=std::uint64_t{a}+b>0xffffffffULL;t.aflag.pf=(std::popcount(v&255U)&1)==0;t.aflag.af=((a^b^v)&16)!=0;t.aflag.zf=v==0;t.aflag.sf=v>>31;t.aflag.of=((~(a^b)&(a^v))>>31)&1;return t;}
FaultReason denied(Context&c){try{c.invoke();}catch(const Fault&f){++faults;return f.reason();}throw std::runtime_error("Required entry denial missing");}
void retry(Fixture&f){const auto state=bytes(f.c.state());const auto soft=fxbytes(f.r);const auto mem=memory(f.r);const auto current=f.r.cpu();const auto events=f.c.events().size(),calls=f.r.calls().size();const auto diag=f.c.diagnostic();check(denied(f.c)==FaultReason::poisoned,"Actual poisoned retry denial");check(bytes(f.c.state())==state&&fxbytes(f.r)==soft&&same(memory(f.r),mem)&&f.r.cpu()==current&&f.c.events().size()==events&&f.r.calls().size()==calls&&owner==nullptr&&!f.c.running(),"Poison retry leaves whole State/softwareFX/pages/TIB/CPU/events/ledger/owner unchanged");check(f.c.diagnostic().pc==diag.pc&&f.c.diagnostic().address==diag.address&&f.c.diagnostic().events==diag.events&&f.c.diagnostic().reason==diag.reason,"Own first origin instrumentation retained after repair/retry");++retries;}
void source_test(std::span<const std::byte>g,const std::string&hash,unsigned seed){++scenarios;Fixture f(g,hash,seed);const auto before=f.c.state();auto mem=memory(f.r);const auto trace=predict(mem,before,f.r.fs_base().value);const auto after=expected(before,trace[13].value);const auto soft=fxbytes(f.r);check(denied(f.c)==FaultReason::unresolved_import&&f.r.poisoned()&&!f.c.running()&&owner==nullptr,"Exact first required service remains unresolved and root poisoned");check(bytes(f.c.state())==bytes(after)&&fxbytes(f.r)==soft&&same(memory(f.r),mem),"Own whole3504 State/whole two pages/three TIB regions/internalFX prefix model");auto wanted=cpu(after);wanted.esp+=4;wanted.eip=0x5ac3cf;check(f.r.cpu()==wanted,"RuntimeCPU actual CALL projection distinct from source raw-target State");check(f.c.events().size()==15,"Exact observed memory prefix count");for(unsigned i=0;i<15;++i){const auto&a=f.c.events()[i];const auto&e=trace[i];check(a.pc==e.pc&&a.address==e.address&&a.value==e.value&&a.width==e.width&&a.write==e.write,"Every actual source memory-event value/order");}check(f.r.calls().size()==1&&!f.r.calls()[0].completed&&f.r.calls()[0].target.value==entry,"No fabricated import/root successful route");auto chain=f.r.seh_chain();check(chain.size()==1&&chain[0].frame.value==frame-20&&chain[0].previous.value==0xffffffff&&chain[0].handler.value==0x5ac586,"Actual translated guest FS/exception frame installed; dispatch not executed");check(f.c.diagnostic().pc==trace[13].value&&f.c.diagnostic().address==slot&&f.c.diagnostic().events==15,"First bridge denial instrumentation records source raw target separately from Runtime CALL site");retry(f);++source_rows;}
void faults_test(std::span<const std::byte>g,const std::string&hash){constexpr unsigned counts[]{1,4,6,13,14,15,15,0,0,0,0,0};constexpr unsigned pcs[]{0x5ac3a3,0x5ac3af,0x5ac3b6,0x5ac3cf,0x5ac3cf};constexpr unsigned address[]{frame-8,0,0,slot,frame-144};for(unsigned mode=1;mode<=12;++mode){++scenarios;Fixture f(g,hash,mode,mode!=10);const auto raw=f.r.memory().load<unsigned>({slot}),source=f.r.memory().load<unsigned>({entry+400});f.c.mode(mode);if(mode==8)f.c.change(entry+400,0x90909090);if(mode==9)f.r.memory().protect({0x20001000},Permissions::read);if(mode==12)f.c.state().addr.fs_base.dword=0x34567000;FaultReason reason{};if(mode==11){std::string error;std::thread t([&]{try{reason=denied(f.c);}catch(const std::exception&e){error=e.what();}});t.join();check(error.empty(),"Sequential wrong-thread adapter refusal caught without process abort");}else reason=denied(f.c);check(f.r.poisoned()&&owner==nullptr&&!f.c.running()&&f.r.calls().size()==1&&!f.r.calls()[0].completed,"Entered outer frame terminal faults remain incomplete and cleanup owner");const unsigned count=mode==12?4:counts[mode-1];check(f.c.events().size()==count,"Actual checked-memory/frame/source/seed/thread denial prefix");if(mode<=5){const auto d=f.c.diagnostic();check(d.pc==pcs[mode-1]&&d.address==(mode==2||mode==3?f.r.fs_base().value:address[mode-1])&&d.events==count,"Actual typed checked-memory origin PC/address and pre-failure event count");}if(mode==7)check(reason==FaultReason::invalid_binding,"Owning raw IAT mutation rejected after actual read/CALL before missing-service resolution");if(mode==9)check(reason==FaultReason::memory_access&&f.c.diagnostic().reason.empty(),"Outer-frame write fails before adapter enters; Runtime still poisons entered outer frame");repair(f,raw,source);f.c.state().addr.fs_base.dword=f.r.fs_base().value;f.r.mark_remill_seeded();retry(f);}}
void refusals(std::span<const std::byte>g,const std::string&hash){
 {++scenarios;Fixture f(g,hash);const auto state=bytes(f.c.state());const auto mem=memory(f.r);bool no=false;try{f.c.invoke(0x12345678);}catch(const Fault&e){no=e.reason()==FaultReason::abi_violation;}check(no&&!f.r.poisoned()&&f.r.calls().empty()&&bytes(f.c.state())==state&&same(memory(f.r),mem)&&owner==nullptr,"Pre-routing malformed return refused with full unchanged caller");check(denied(f.c)==FaultReason::unresolved_import,"Corrected pre-routing return reaches actual first service later");retry(f);++unentered;}
 {++scenarios;Fixture f(g,hash);const auto state=bytes(f.c.state());const auto mem=memory(f.r);owner=&f.c;bool no=false;try{f.c.invoke();}catch(const std::exception&){no=true;}check(no&&!f.r.poisoned()&&f.r.calls().empty()&&bytes(f.c.state())==state&&same(memory(f.r),mem)&&owner==&f.c,"Nested lexical owner refusal before routing preserves outer owner");owner=nullptr;check(denied(f.c)==FaultReason::unresolved_import,"Released outer owner enables first required service route");retry(f);++unentered;}
 {++scenarios;Fixture f(g,hash);bool no=false;try{f.r.invoke({entry});}catch(const Fault&e){no=e.reason()==FaultReason::memory_access;}check(no&&f.r.poisoned()&&f.c.events().empty()&&owner==nullptr,"Bypassed adapter owner is a caught entered terminal fault");retry(f);}
}
int main(int argc,char**argv){try{check(argc==3,"Own exact image/object arguments");const auto g=file(argv[1]),obj=file(argv[2]);check(m4::sha256(g)==m4::admitted_image_hash,"Own actual game image identity");const auto hash=m4::sha256(obj);for(unsigned seed=0;seed<4;++seed)source_test(g,hash,seed);faults_test(g,hash);refusals(g,hash);std::cout<<"{\"passed\":true,\"checks\":"<<checks<<",\"scenarios\":"<<scenarios<<",\"predicted_source_rows\":"<<source_rows<<",\"actual_denial_calls\":"<<faults<<",\"poisoned_retries\":"<<retries<<",\"unentered_corrected_reuses\":"<<unentered<<",\"original_execution\":false,\"full_CRT\":false}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<" checks="<<checks<<" scenarios="<<scenarios<<'\n';return 1;}}
